#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long modPow(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y;
    cin >> x >> y;

    if (x == 0 || y % x != 0) {
        cout << 0;
        return 0;
    }

    long long n = y / x;
    vector<long long> primes;
    long long value = n;

    for (long long p = 2; p <= value / p; ++p) {
        if (value % p == 0) {
            primes.push_back(p);
            while (value % p == 0) value /= p;
        }
    }
    if (value > 1) primes.push_back(value);

    long long answer = 0;
    int count = primes.size();

    for (int mask = 0; mask < (1 << count); ++mask) {
        long long divisor = 1;
        int bits = 0;

        for (int i = 0; i < count; ++i) {
            if (mask & (1 << i)) {
                divisor *= primes[i];
                ++bits;
            }
        }

        long long term = modPow(2, n / divisor - 1);
        if (bits & 1)
            answer = (answer - term + MOD) % MOD;
        else
            answer = (answer + term) % MOD;
    }

    cout << answer;
    return 0;
}

